// demo/beta-quality-completion/quote-client.mjs
var quoteOrigin = "https://hanganggak-realtime-demo.onrender.com";
async function cachedQuote(id, signal) {
  const response = await fetch(quoteOrigin + "/quotes/" + encodeURIComponent(id), { cache: "no-store", signal });
  if (!response.ok) throw Error("\uC2DC\uC138 \uC11C\uBC84 \uC5F0\uACB0 \uC2E4\uD328");
  return response.json();
}
function stockWithQuote(stock, quote) {
  if (!stock || quote?.id !== stock.id || quote.mode !== "live" || !Number.isFinite(quote.change) || !(quote.price > 0)) return null;
  return { ...stock, change: quote.change, quote, map: quote.change < 0 ? "river" : "rooftop" };
}

// demo/shared/quote-display.mjs
var signed = (v, digits = 2) => Number.isFinite(v) ? `${v >= 0 ? "+" : ""}${v.toFixed(digits)}%` : "\uC2DC\uC138 \uC5C6\uC74C";
function quoteDisplay(q) {
  if (!q || q.mode !== "live") return { price: "", change: "", status: "\uB370\uBAA8 \xB7 \uAC00\uC0C1 \uB4F1\uB77D\uB960", time: "" };
  const labels = { open: "\uC7A5\uC911", closed: "\uB9C8\uAC10", holiday: "\uD734\uC7A5", delayed: "\uC2DC\uC138 \uC9C0\uC5F0 \xB7 \uB9C8\uC9C0\uB9C9 \uD655\uC778\uAC12", failed: "\uC218\uC9D1 \uC2E4\uD328 \xB7 \uB9C8\uC9C0\uB9C9 \uC815\uC0C1\uAC12", unavailable: "\uC2DC\uC138 \uC5C6\uC74C", unknown: "\uC7A5\uC0C1\uD0DC \uBBF8\uD655\uC778" };
  const time = (value, zone = "Asia/Seoul") => value ? new Date(value).toLocaleString("ko-KR", { timeZone: zone, month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false }) : null;
  const usd2 = q.currency === "USD";
  const sessionLabels = { pre: "\uD504\uB9AC\uC7A5", regular: "\uC815\uADDC\uC7A5", post: "\uC560\uD504\uD130\uC7A5" };
  const market = usd2 ? sessionLabels[q.session] : q.source ?? "\uB124\uC774\uBC84 \uC6F9";
  const status2 = [market, labels[q.status] ?? labels.unknown].filter(Boolean).join(" \xB7 ");
  const traded = q.quoteAt ? usd2 ? "\uBBF8 \uB3D9\uBD80 " + time(q.quoteAt, "America/New_York") : "\uC2DC\uC138 " + time(q.quoteAt) : "\uC2DC\uC138 \uC2DC\uAC01 \uBBF8\uC81C\uACF5";
  const valid = Number.isFinite(q.price) && Number.isFinite(q.change);
  return { price: valid ? usd2 ? q.price.toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 4 }) : `${q.price.toLocaleString("ko-KR")}\uC6D0` : "\uC2DC\uC138 \uC5C6\uC74C", change: valid ? signed(q.change) : "", status: status2, time: `${traded} \xB7 ${q.fetchedAt ? (usd2 ? "\uC11C\uC6B8 \uC870\uD68C " : "\uC870\uD68C ") + time(q.fetchedAt) : "\uC815\uC0C1 \uC870\uD68C \uC5C6\uC74C"}` };
}

// demo/beta-quality-completion/us-quote-dialog.mjs
var exchanges = /* @__PURE__ */ new Map([
  ["NASDAQ", "NASDAQ"],
  ["NYSE", "NYSE"],
  ["NYSE Arca", "AMEX"],
  ["NYSE American", "AMEX"],
  ["Cboe BZX", "CBOE"]
]);
function externalLink(text, url) {
  const link = document.createElement("a");
  link.textContent = text;
  link.href = url;
  link.target = "_blank";
  link.rel = "noopener noreferrer";
  return link;
}
function showUSQuote(stock, destination) {
  const dialog = document.createElement("dialog");
  dialog.className = "us-quote-sheet";
  dialog.setAttribute("aria-labelledby", "us-quote-title");
  const header = document.createElement("header");
  const title = document.createElement("h2");
  title.id = "us-quote-title";
  title.textContent = stock.name;
  const close = document.createElement("button");
  close.type = "button";
  close.textContent = "\uB2EB\uAE30";
  close.onclick = () => dialog.close();
  header.append(title, close);
  const listing = document.createElement("p");
  listing.textContent = [stock.ticker, stock.market, stock.type === "ETF" ? "ETF" : "\uC8FC\uC2DD"].join(" \xB7 ");
  dialog.append(header, listing);
  const exchange = exchanges.get(stock.market);
  if (exchange) {
    const url = new URL("https://www.tradingview-widget.com/embed-widget/single-quote/");
    url.searchParams.set("locale", "kr");
    url.hash = encodeURIComponent(JSON.stringify({
      symbol: exchange + ":" + stock.ticker,
      colorTheme: "dark",
      isTransparent: false,
      width: "100%",
      "page-uri": location.origin + location.pathname
    }));
    const widget = document.createElement("iframe");
    widget.title = stock.ticker + " \uAC00\uACA9\uACFC \uB4F1\uB77D\uB960";
    widget.src = url.href;
    const attribution = externalLink(
      "TradingView\uC5D0\uC11C \uBCF4\uAE30 \u2197",
      "https://www.tradingview.com/symbols/" + exchange + "-" + encodeURIComponent(stock.ticker) + "/"
    );
    attribution.className = "quote-provider";
    dialog.append(widget, attribution);
  }
  const naver = externalLink(destination.label + " \u2197", destination.url);
  naver.className = "quote-naver";
  dialog.append(naver);
  dialog.addEventListener("close", () => dialog.remove(), { once: true });
  dialog.addEventListener("keydown", (event) => event.stopPropagation());
  dialog.addEventListener("click", (event) => {
    if (event.target !== dialog) return;
    const bounds = dialog.getBoundingClientRect();
    if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) dialog.close();
  });
  document.body.append(dialog);
  dialog.showModal();
}

