// demo/shared/stock-search.mjs
var normalizeSearch = (value) => String(value).normalize("NFKC").replace(/\s+/gu, "").toLocaleLowerCase("ko");
var byCode = (a, b) => a.id.localeCompare(b.id);
function searchStocks(query = "", sort = "cap", stocks = DEMO_STOCKS, counts = {}) {
  const q = normalizeSearch(query);
  const tickerQuery = q.replace(/[-/]/g, ".");
  const matches = stocks.filter((stock) => {
    if (!q || normalizeSearch(stock.name).includes(q)) return true;
    if (stock.ticker) return stock.ticker.toLowerCase().startsWith(tickerQuery) || normalizeSearch(stock.english ?? "").includes(q);
    return stock.id.toLowerCase().startsWith(q);
  });
  return matches.sort((a, b) => {
    if (sort === "rooms") {
      const people = (counts?.[b.id] ?? 0) - (counts?.[a.id] ?? 0);
      if (people) return people;
    } else if (q) {
      const exact = Number(b.ticker?.toLowerCase() === tickerQuery) - Number(a.ticker?.toLowerCase() === tickerQuery);
      if (exact) return exact;
    }
    if (sort === "code") return byCode(a, b);
    if (sort === "name") return a.name.localeCompare(b.name, "ko") || byCode(a, b);
    const cap = (s) => Number.isFinite(s.marketCap) ? s.marketCap : -Infinity;
    return cap(b) - cap(a) || 0 || ((a.marketCapRank ?? Infinity) - (b.marketCapRank ?? Infinity) || 0) || byCode(a, b);
  });
}

